using System.Text.Json;
using System.Text.Json.Serialization;

namespace Kermaria.ApiInternal.Services;

/// <summary>
/// Seed fermé du catalogue éditorial public. Les montants ne figurent pas ici :
/// Billing demeure la seule autorité numérique. Après le premier seed, la base
/// conserve toute modification effectuée depuis l'administration.
/// </summary>
internal static class StorefrontContentSeed
