    private static Page Category(string seoTitle, string seoDescription, string title, string lead, string ctaLabel, string ctaHref, string firstHeading, string firstBody, string secondHeading, string secondBody, IReadOnlyList<Link> links)
        => PageOf(seoTitle, seoDescription, title, lead, ctaLabel, ctaHref,
            [S(firstHeading, firstBody), S(secondHeading, secondBody), S("Pour avancer", "Consultez une page de service précise ou demandez un audit : la proposition tiendra compte de l’existant, des contraintes et du périmètre utile.")],
            [F("Ces services sont-ils disponibles en libre-service ?", "Seulement lorsque le parcours le précise. Les prestations nécessitant une étude restent sur devis."), F("Puis-je demander un seul service ?", "Oui. Les dépendances éventuelles sont expliquées avant la mise en place."), F("Comment commencer ?", "Choisissez une page liée ou utilisez le diagnostic pour décrire votre besoin.")], links);

    private static Page Seo(string seoTitle, string seoDescription, string title, string lead, string ctaLabel, string ctaHref, string firstHeading, string firstBody, string secondHeading, string secondBody, IReadOnlyList<Faq> faq, IReadOnlyList<Link> links, string? pricingBody = null)
        => PageOf(seoTitle, seoDescription, title, lead, ctaLabel, ctaHref,
            [S(firstHeading, firstBody), S(secondHeading, secondBody), S("Tarif et devis", pricingBody ?? "Le service est qualifié avant mise en œuvre. Lorsque le prix ne peut pas être déterminé immédiatement, nous vous proposons un devis adapté à votre besoin.")], faq, links);

    private static Page PageOf(string seoTitle, string seoDescription, string title, string lead, string ctaLabel, string ctaHref, IReadOnlyList<Section> sections, IReadOnlyList<Faq> faq, IReadOnlyList<Link> links, IReadOnlyList<ProblemEntry>? problemEntries = null)
        => new(seoTitle, seoDescription, title, lead, ctaLabel, ctaHref, sections, faq, links, problemEntries);

    private static Section S(string heading, string body) => new(heading, body);
    private static Faq F(string question, string answer) => new(question, answer);
    private static Link L(string label, string href) => new(label, href);
    private static ProblemEntry P(string title, string description, string href) => new(title, description, href);
